    async def test_call(
        self,
        id: str,
        branch_id: str,
        *,
        include_draft: typing.Optional[bool] = OMIT,
        revision_id: typing.Optional[str] = OMIT,
        mode: typing.Optional[TestCallV2RequestMode] = OMIT,
        to_phone: typing.Optional[str] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> TestCallAgentVersioningBranchesResponse:
        """
        Start a test call using the branch's current config. Send `includeDraft: true` to test the open draft, or send `revisionId` to test a specific committed revision on the branch. Sending both is a validation error.

        The response always includes `conversationId` and `callId`. For `webcall` and `chat`, it also includes `token`, `roomName`, and `host`. Those fields are omitted for `telephony`.

        Parameters
        ----------
        id : str
            The agent ID.

        branch_id : str
            The branch ID.

        include_draft : typing.Optional[bool]
            When `true`, the test call uses the branch's open draft. Mutually exclusive with `revisionId`.

        revision_id : typing.Optional[str]
            Test against a specific committed revision on the branch. Mutually exclusive with `includeDraft: true`.

        mode : typing.Optional[TestCallV2RequestMode]

        to_phone : typing.Optional[str]
            E.164-formatted number. Required when `mode` is `telephony`. Omit for `webcall` and `chat`.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        TestCallAgentVersioningBranchesResponse
            Test call initiated.

        Examples
        --------
        import asyncio

        from smallestai import AsyncSmallestAI

        client = AsyncSmallestAI(
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            await client.atoms.agent_versioning_branches.test_call(
                id="id",
                branch_id="branchId",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.test_call(
            id,
            branch_id,
            include_draft=include_draft,
            revision_id=revision_id,
            mode=mode,
            to_phone=to_phone,
            request_options=request_options,
        )
        return _response.data
